const SKIP_TO_GAMEPLAY = false; // Set to true to skip menus and go straight to game
const W = 800; // Game screen width in pixels
const H = 600; // Game screen height in pixels

// Difficulty: 0 = EASY (sparse notes), 1 = MEDIUM (standard), 2 = HARD (fast dense streams)
const DEFAULT_DIFFICULTY = 1;
// Minimum seconds between notes per difficulty mode [EASY, MEDIUM, HARD] (higher = more spaced out notes)
const DIFFICULTY_GAPS = [0.24, 0.14, 0];

// Receptor arrow bounce animation on hit
const BOUNCE_SCALE = 0.25;  // Scale pulse on hit (+25% size boost; increase e.g. 0.4 - 0.6 for bigger pop)
const BOUNCE_Y = 8;          // Vertical displacement in pixels (hops upward by 8px on hit)
const BOUNCE_DECAY = 0.005;  // Decay rate per ms (lower = longer bounce, higher = snappier)

// Hit window & timing tolerances (in pixels)
const HIT_WIN = 50;          // Total hit window in pixels (~145ms window, DDR/FNF standard Good)
const PERFECT_WIN = 18;      // Perfect hit window in pixels (~52ms window for precision bonus)
const MISS_TOL = 50;         // Distance in pixels beyond hit line before a note is auto-missed

// Tug-of-war bar balance & damage/penalty values
const BAR_MAX = 100;         // Tug-of-war meter limit (+100 = Player 1 wins, -100 = Player 2 wins)
const DMG_PERFECT = 2.0;     // Bar shift amount awarded on a Perfect hit
const DMG_GOOD = 1.0;        // Bar shift amount awarded on a Good hit
const MISS_PEN = 2.5;        // Bar penalty deducted on Miss or empty ghost tap

// Note travel speed & layout
const HIT_Y = 518;           // Vertical screen position (Y coordinate in px) of receptor hit line
const TRAVEL_TIME = 1.5;     // Fall duration in seconds from top of screen to hit line
const ARROW_SCALE = 5.2;     // Base visual scale multiplier for arrow sprites
const LEAD_IN = 2;           // Lead-in delay in seconds before notes appear
const SEC_LEN = 8;           // Duration in seconds of each player's alternating turn
const PAD = 160;             // Background margin padding in pixels for camera pans
