// Base91 decoding table & constants for compact lossless MIDI storage
const A = "!#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{}~";
const B = A.length; // Radix size (91)
const Z = B - 1; // End-of-varint marker index (90)
